// The traps behind every function the port cannot call yet (dread_port.h). The thunks that jump here
// are generated by tools/port_link.py from the whole-program link's undefined symbols: one per
// function with no source, and one per call the link refused to alias because the caller's argument
// classes differ from the definition's. Each loads the function's original address as the argument.
// The data loader writes the same kind of thunk for the game's pointers to code and imports the port
// does not define. By default each trap aborts; with DREAD_TRAP=log it reports each function once
// and returns 0, so that a run lists the whole boot's missing functions in order.

#include "dread_port.h"

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <mutex>
#include <unordered_set>

namespace {

bool LogMode() {
    static const bool on = [] {
        const char* mode = std::getenv("DREAD_TRAP");
        return mode && std::strcmp(mode, "log") == 0;
    }();
    return on;
}

// True the first time a key is seen; counts the distinct ones.
bool FirstTime(u64 key, u64* ordinal) {
    static std::mutex lock;
    static std::unordered_set<u64> seen;
    std::lock_guard<std::mutex> hold(lock);
    const bool first = seen.insert(key).second;
    *ordinal = seen.size();
    return first;
}

[[noreturn]] void Stop() {
    std::fflush(stderr);
    std::abort();
}

}  // namespace

extern "C" u64 dread_port_missing_function(u64 address) {
    if (!LogMode()) {
        std::fprintf(stderr, "dread: call to a function with no source yet: fn_%llx (see data/functions/)\n",
                     static_cast<unsigned long long>(address));
        Stop();
    }
    u64 n;
    if (FirstTime(address, &n))
        std::fprintf(stderr, "dread: trap %llu (continuing): fn_%llx\n", static_cast<unsigned long long>(n),
                     static_cast<unsigned long long>(address));
    return 0;
}

extern "C" u64 dread_port_mismatched_call(u64 address) {
    if (!LogMode()) {
        std::fprintf(stderr,
                     "dread: call to fn_%llx through a declaration whose argument classes differ from the definition's"
                     " (class_mismatch in build/port/link/link.json; fix the declaration)\n",
                     static_cast<unsigned long long>(address));
        Stop();
    }
    u64 n;
    if (FirstTime(address | (u64(1) << 63), &n))
        std::fprintf(stderr, "dread: trap %llu (continuing): fn_%llx, mismatched call\n",
                     static_cast<unsigned long long>(n), static_cast<unsigned long long>(address));
    return 0;
}

extern "C" u64 dread_port_missing_import(const char* name) {
    if (!LogMode()) {
        std::fprintf(stderr, "dread: call to an import the port does not define yet: %s (the game's data points at it)\n",
                     name);
        Stop();
    }
    u64 n;
    if (FirstTime(reinterpret_cast<u64>(name), &n))
        std::fprintf(stderr, "dread: trap %llu (continuing): %s\n", static_cast<unsigned long long>(n), name);
    return 0;
}
